function updateMatrix(mat) {
  const rows = mat.length, cols = mat[0].length;
  const INF = rows + cols;                // longer than any real distance
  const dist = mat.map((row) => row.map((v) => (v === 0 ? 0 : INF)));
  // Pass 1, top-left first: take the best from the cell above and the cell to the left.
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (r > 0) dist[r][c] = Math.min(dist[r][c], dist[r - 1][c] + 1);
      if (c > 0) dist[r][c] = Math.min(dist[r][c], dist[r][c - 1] + 1);
    }
  }
  // Pass 2, bottom-right first: now also from the cell below and the cell to the right.
  for (let r = rows - 1; r >= 0; r--) {
    for (let c = cols - 1; c >= 0; c--) {
      if (r < rows - 1) dist[r][c] = Math.min(dist[r][c], dist[r + 1][c] + 1);
      if (c < cols - 1) dist[r][c] = Math.min(dist[r][c], dist[r][c + 1] + 1);
    }
  }
  return dist;
}

